"use strict";
const teams = {
  Birch: ["#42623d", "#e0ebd5", "M8 1 15 14H1z"],
  Chalk: ["#48678e", "#e0e8f2", "m8 1 7 7-7 7-7-7z"],
  Fern: ["#367660", "#daede0", "M2 14C1 5 5 2 14 2c0 9-4 13-12 12z"],
  Lark: ["#9c5a31", "#f6e4d3", "m1 4 7 4 7-4-7 10z"],
  Moss: ["#6a7031", "#e9ebce", "M2 3h12v10H2z"],
  Reed: ["#775682", "#ece1f0", "M2 13 5 3h3L5 13zm6 0 3-10h3l-3 10z"]
};
const times = ["6:30", "6:55", "7:20"];
const ends = ["6:55", "7:20", "7:45"];
const seed = [["Birch","Chalk"],["Fern","Lark"],["Moss","Reed"],["Birch","Fern"],["Chalk","Moss"],["Lark","Reed"]];
const $ = id => document.getElementById(id);
const meeting = new Date();
meeting.setHours(12,0,0,0);
meeting.setDate(meeting.getDate() + (11 - meeting.getDay()) % 7);
const dateKey = () => [meeting.getFullYear(), String(meeting.getMonth()+1).padStart(2,"0"), String(meeting.getDate()).padStart(2,"0")].join("-");
const key = () => "thursday-league.v1." + dateKey();
const empty = () => Array(6).fill(null);
let matches, active, fault;
function read() {
  const raw = localStorage.getItem(key());
  if (raw === null) return empty();
  const slots = JSON.parse(raw);
  if (!Array.isArray(slots) || slots.length !== 6 || !slots.every(p => p === null || (Array.isArray(p) && p.length === 2 && p.every(t => Object.hasOwn(teams,t))))) throw Error("Invalid schedule");
  return slots;
}
function load() {
  fault = "";
  try {
    if (!localStorage.getItem("thursday-league.started")) {
      if (!localStorage.getItem(key())) localStorage.setItem(key(),JSON.stringify(seed));
      localStorage.setItem("thursday-league.started","1");
    }
    matches = read();
  } catch { matches = empty(); fault = "Cannot load local schedule. Check browser storage and reload."; }
  render();
}
const icon = path => '<svg aria-hidden="true" viewBox="0 0 24 24"><path d="'+path+'"/></svg>';
const tableIcon = icon("M3 5h18v14H3zM12 3v18M3 12h18");
const pencil = icon("m5 15 10-10 4 4L9 19l-5 1zM13 7l4 4");
function teamRow(name) {
  const [tone,tint,path] = teams[name];
  return '<div class="team"><span class="mark" style="--tone:'+tone+';--tint:'+tint+'"><svg aria-hidden="true" viewBox="0 0 16 16"><path d="'+path+'"/></svg></span>'+name+'</div>';
}
function render() {
  $("date").textContent = meeting.toLocaleDateString("en-US",{weekday:"short",month:"short",day:"numeric",year:"numeric"});
  let html = '<div class="colhead">TIME SLOT</div>'+[1,2].map(n=>'<div class="colhead">'+tableIcon+' TABLE '+n+'</div>').join("");
  times.forEach((time,row) => {
    html += '<div class="cell time"><span class="slotno">SLOT 0'+(row+1)+'</span><strong>'+time+' <small>PM</small></strong></div>';
    for (let table=0; table<2; table++) {
      const index = row*2+table, pair = matches[index];
      const label = (pair ? "Edit "+pair.join(" vs ") : "Add pairing")+", table "+(table+1)+", "+time+" PM";
      html += '<div class="cell match">'+(pair ? '<div class="pair">'+pair.map(teamRow).join("")+'</div>' : '<span class="empty">Open table</span>')+'<button class="edit" data-index="'+index+'" aria-label="'+label+'" '+(fault?"disabled":"")+'>'+ (pair?pencil:icon("M12 4v16M4 12h16"))+'</button></div>';
    }
  });
  $("board").innerHTML = html;
  $("progress").textContent = matches.filter(Boolean).length+" of 6 pairings scheduled";
  $("saved").textContent = fault || "✓  Saved on this device";
  $("print").disabled = Boolean(fault);
}
function issue(pair, slots) {
  if (!pair.every(Boolean)) return "Choose both teams to save this pairing.";
  if (pair[0] === pair[1]) return "Choose two different teams for this pairing.";
  const other = active ^ 1;
  const booked = pair.filter(t=>slots[other]?.includes(t));
  if (booked.length) return booked.join(" and ")+" already scheduled on Table "+(other%2+1)+" at "+times[Math.floor(active/2)]+" PM.";
  return "";
}
function check() {
  const error = issue([$("first").value,$("second").value],matches);
  $("error").textContent = error;
  $("form").querySelector('[type="submit"]').disabled = Boolean(error);
}
for (const id of ["first","second"]) {
  $(id).innerHTML = '<option value="">Choose team</option>'+Object.keys(teams).map(t=>'<option>'+t+'</option>').join("");
  $(id).onchange = check;
}
$("board").onclick = event => {
  const button = event.target.closest("button[data-index]");
  if (!button) return;
  active = Number(button.dataset.index);
  const row = Math.floor(active/2), pair = matches[active];
  $("context").textContent = "TABLE "+(active%2+1)+"  /  SLOT 0"+(row+1);
  $("slot").textContent = $("date").textContent+" · "+times[row]+"–"+ends[row]+" PM";
  $("editTitle").textContent = pair ? "Edit pairing" : "Add pairing";
  $("first").value = pair?.[0] || "";
  $("second").value = pair?.[1] || "";
  $("clear").hidden = !pair;
  check();
  $("editor").showModal();
  $("first").focus();
};
function save(pair) {
  try {
    const slots = read();
    if (JSON.stringify(slots[active]) !== JSON.stringify(matches[active])) {
      $("error").textContent = "This pairing changed in another window. Close and reopen the editor.";
      return;
    }
    const error = pair && issue(pair, slots);
    if (error) { $("error").textContent = error; return; }
    slots[active] = pair;
    localStorage.setItem(key(), JSON.stringify(slots));
    matches = slots;
    render();
    $("editor").close();
  } catch { $("error").textContent = "Could not save. Check browser storage and try again."; }
}
$("editor").onclose = () => {load(); $("board").querySelector('[data-index="'+active+'"]').focus();};
$("form").onsubmit = e => { e.preventDefault(); save([$("first").value,$("second").value]); };
$("clear").onclick = () => save(null);
$("close").onclick = () => $("editor").close();
for (const [id, days] of [["prev",-7],["next",7]]) {
  $(id).onclick = () => {meeting.setDate(meeting.getDate()+days);load();};
}
$("print").onclick = () => window.print();
window.addEventListener("storage",e=>{if ((!e.key || e.key===key()) && !$("editor").open) load();});
load();

"use strict";

const teams = ["Birch", "Chalk", "Fern", "Lark", "Moss", "Reed"];
const slots = [
  { start: "6:30", end: "6:55" },
  { start: "6:55", end: "7:20" },
  { start: "7:20", end: "7:45" }
];
const storageKey = "thursday-table-tennis-v1";
const dateFormat = new Intl.DateTimeFormat("en-US", {
  weekday: "long", month: "long", day: "numeric", year: "numeric", timeZone: "UTC"
});
const $ = id => document.getElementById(id);
const dateInput = $("date");
const editor = $("editor");
const form = $("pairing-form");
const firstTeam = $("team-a");
const secondTeam = $("team-b");

function dateKey(date) {
  return date.toISOString().slice(0, 10);
}

function isThursday(key) {
  if (typeof key !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(key) ||
      key < dateInput.min || key > dateInput.max) return false;
  const date = new Date(key);
  return date.getUTCDay() === 4 && dateKey(date) === key;
}

function shiftDate(key, days) {
  const date = new Date(key);
  date.setUTCDate(date.getUTCDate() + days);
  return dateKey(date);
}

function upcomingThursday() {
  const now = new Date();
  const localDay = new Date(Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()));
  return shiftDate(dateKey(localDay), (4 - localDay.getUTCDay() + 7) % 7);
}

function validPair(pair) {
  return Array.isArray(pair) && pair.length === 2 &&
    teams.includes(pair[0]) && teams.includes(pair[1]) && pair[0] !== pair[1];
}

function load() {
  const fallback = { date: upcomingThursday(), evenings: {}, problem: "" };
  let raw;
  try {
    raw = localStorage.getItem(storageKey);
  } catch {
    return { ...fallback, problem: "Browser storage is unavailable. Changes may be lost when you close this page." };
  }
  if (raw === null) return fallback;
  try {
    const stored = JSON.parse(raw);
    if (!isThursday(stored.date) || !stored.evenings ||
        typeof stored.evenings !== "object" || Array.isArray(stored.evenings)) throw new Error();
    for (const [key, matches] of Object.entries(stored.evenings)) {
      if (!isThursday(key) || !Array.isArray(matches) || matches.length !== 6 ||
          !matches.every(pair => pair === null || validPair(pair))) throw new Error();
    }
    return { ...stored, problem: "" };
  } catch {
    return { ...fallback, problem: "Saved schedules could not be read. Saving is paused to preserve the existing data." };
  }
}

let { date, evenings, problem } = load();
const savingPaused = problem.startsWith("Saved schedules");
let editedIndex = null;

function save() {
  if (savingPaused) return;
  try {
    localStorage.setItem(storageKey, JSON.stringify({ date, evenings }));
    problem = "";
  } catch {
    problem = "Changes could not be saved. Keep this page open to retain your edits.";
  }
}

function matchesForDay() {
  return evenings[date] ?? Array(6).fill(null);
}

function conflictIn(matches, slot) {
  const [left, right] = matches.slice(slot * 2, slot * 2 + 2);
  return left && right ? left.filter(team => right.includes(team)) : [];
}

function teamMarkup(team) {
  return '<span class="team-dot ' + team.toLowerCase() + '" aria-hidden="true"></span>' + team;
}

function matchButton(pair, index, conflicts) {
  const slot = slots[Math.floor(index / 2)];
  const table = index % 2 + 1;
  const description = pair ? pair.join(" vs ") : "Add pairing";
  const warning = conflicts.length ? " · Double booking" : "";
  const body = pair
    ? '<span class="matchup"><span>' + teamMarkup(pair[0]) + '</span><small>vs</small><span>' +
      teamMarkup(pair[1]) + '</span></span><span class="match-action">' + (warning ? "Double booking" : "Edit pairing") + '</span>'
    : '<span class="add-mark" aria-hidden="true">+</span><span>Add pairing</span>';
  return '<button type="button" class="match ' + (pair ? "booked" : "open") + (warning ? " conflict" : "") +
    '" data-index="' + index + '" aria-label="' + slot.start + ' p.m., Table ' + table +
    ', ' + description + warning + '">' + body + '</button>';
}

function renderPrint(matches, conflicts, dateLabel) {
  const rows = slots.map((slot, index) => {
    const cells = matches.slice(index * 2, index * 2 + 2).map(pair => pair
      ? '<td><strong>' + pair[0] + '</strong><span>vs</span><strong>' + pair[1] + '</strong></td>'
      : '<td class="print-open">Open table</td>').join("");
    return '<tr><th scope="row">' + slot.start + '–' + slot.end + '<span>p.m.</span></th>' + cells + '</tr>';
  }).join("");
  const warnings = conflicts.filter(Boolean);
  $("print-sheet").innerHTML = '<header><p>Thursday Table Tennis</p><h1>Evening fixtures</h1><p>' +
    dateLabel + '</p></header>' + (warnings.length ? '<div class="print-warning"><strong>Double bookings</strong><p>' +
    warnings.join(" · ") + '</p></div>' : "") +
    '<table aria-label="Evening fixtures"><thead><tr><th scope="col">Time</th><th scope="col">Table 1</th>' +
    '<th scope="col">Table 2</th></tr></thead><tbody>' + rows + '</tbody></table>';
}

function render() {
  const matches = matchesForDay();
  const conflicts = slots.map((_, index) => conflictIn(matches, index));
  const dateLabel = dateFormat.format(new Date(date));
  dateInput.value = date;
  dateInput.removeAttribute("aria-invalid");
  $("date-error").hidden = true;
  $("evening").textContent = dateLabel;
  $("previous").disabled = !isThursday(shiftDate(date, -7));
  $("next").disabled = !isThursday(shiftDate(date, 7));

  $("board").innerHTML =
    '<div class="matrix-head"><span>Time</span><span>Table 1</span><span>Table 2</span></div>' +
    slots.map((slot, index) => '<section class="slot" aria-label="' + slot.start + ' to ' + slot.end +
      ' p.m."><div class="slot-time"><strong>' + slot.start + '</strong><span>to ' + slot.end +
      ' p.m.</span></div><div class="table-label">Table 1</div>' + matchButton(matches[index * 2], index * 2, conflicts[index]) +
      '<div class="table-label">Table 2</div>' + matchButton(matches[index * 2 + 1], index * 2 + 1, conflicts[index]) +
      '</section>').join("");

  const count = matches.filter(Boolean).length;
  $("count").textContent = count + " / 6 filled";
  $("meter-fill").style.width = (count / 6 * 100) + "%";
  const warnings = conflicts.map((overlap, index) => overlap.length
    ? slots[index].start + ' p.m. · ' + overlap.join(" and ") : "");
  const hasConflict = warnings.some(Boolean);
  $("checks").innerHTML = hasConflict
    ? '<p class="check-label problem"><span aria-hidden="true">!</span> Double bookings</p><ul>' +
      warnings.filter(Boolean).map(warning => '<li>' + warning + '</li>').join("") + '</ul>'
    : '<p class="check-label"><span aria-hidden="true">✓</span> No double bookings</p>';

  $("save-status").textContent = problem || "Changes save in this browser";
  $("save-status").classList.toggle("error", Boolean(problem));
  renderPrint(matches, warnings, dateLabel);
}

function setDate(newDate) {
  if (!isThursday(newDate)) {
    $("date-error").textContent = "Choose a Thursday. The board is still showing " +
      dateFormat.format(new Date(date)) + ".";
    $("date-error").hidden = false;
    dateInput.setAttribute("aria-invalid", "true");
    return;
  }
  date = newDate;
  save();
  render();
}

function previewPairing() {
  const first = firstTeam.value;
  const second = secondTeam.value;
  const sameTeam = first && first === second;
  secondTeam.setCustomValidity(sameTeam ? "Choose a different team." : "");
  if (sameTeam) secondTeam.setAttribute("aria-invalid", "true");
  else secondTeam.removeAttribute("aria-invalid");
  const otherTableIndex = editedIndex % 2 === 0 ? editedIndex + 1 : editedIndex - 1;
  const otherTable = matchesForDay()[otherTableIndex];
  const overlap = otherTable ? [...new Set([first, second].filter(team => otherTable.includes(team)))] : [];
  const message = $("pairing-message");
  message.textContent = sameTeam ? "Choose two different teams." :
    overlap.length ? "Double booking · " + overlap.join(" and ") + " already on the other table." : "";
  message.hidden = !message.textContent;
}

function openEditor(index) {
  editedIndex = index;
  const pair = matchesForDay()[index];
  const slot = slots[Math.floor(index / 2)];
  $("editor-context").textContent = slot.start + "–" + slot.end + " p.m. · Table " + (index % 2 + 1);
  $("editor-title").textContent = pair ? "Edit pairing" : "Add pairing";
  firstTeam.value = pair ? pair[0] : "";
  secondTeam.value = pair ? pair[1] : "";
  $("clear").hidden = !pair;
  previewPairing();
  editor.showModal();
}

function updatePairing(pair) {
  const index = editedIndex;
  const matches = [...matchesForDay()];
  matches[index] = pair;
  if (matches.some(Boolean)) evenings[date] = matches;
  else delete evenings[date];
  save();
  editor.close();
  render();
  $("board").querySelector('[data-index="' + index + '"]').focus();
}

$("roster").innerHTML = teams.map(team => "<li>" + teamMarkup(team) + "</li>").join("");
for (const field of [firstTeam, secondTeam]) {
  field.add(new Option("Choose a team", ""));
  for (const team of teams) field.add(new Option(team, team));
  field.addEventListener("change", previewPairing);
}

$("previous").addEventListener("click", () => setDate(shiftDate(date, -7)));
$("next").addEventListener("click", () => setDate(shiftDate(date, 7)));
dateInput.addEventListener("change", () => setDate(dateInput.value));
$("board").addEventListener("click", event => {
  const button = event.target.closest("[data-index]");
  if (button) openEditor(Number(button.dataset.index));
});
$("cancel").addEventListener("click", () => editor.close());
$("clear").addEventListener("click", () => updatePairing(null));
form.addEventListener("submit", event => {
  event.preventDefault();
  const pair = [firstTeam.value, secondTeam.value];
  if (validPair(pair)) updatePairing(pair);
});
$("print").addEventListener("click", () => window.print());
render();

:root {
  color-scheme: light;
  --paper: #f7f5ee;
  --white: #fffefa;
  --ink: #17382f;
  --muted: #52655c;
  --line: #d8dfd5;
  --green: #1c513f;
  --green-deep: #153e31;
  --mint: #e5eee4;
  --orange: #f9aa69;
  --warning: #8f3215;
  --warning-bg: #fff1e7;
  font: 16px/1.5 system-ui, sans-serif;
}

*, *::before, *::after { box-sizing: border-box; }
body { margin: 0; color: var(--ink); background: var(--paper); }
h1, h2, p { margin: 0; }
button, input, select { font: inherit; }
button { cursor: pointer; touch-action: manipulation; }
button:disabled { cursor: default; opacity: .45; }
:focus-visible { outline: 3px solid #a34c24; outline-offset: 3px; }
[hidden] { display: none !important; }
.wrap { width: min(1184px, calc(100% - 80px)); margin-inline: auto; }

.masthead { background: var(--green-deep); color: var(--white); }
.masthead-inner { min-height: 68px; display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.league { display: flex; align-items: center; gap: 12px; font-weight: 750; letter-spacing: .015em; }
.league-mark { width: 24px; height: 16px; border: 1.5px solid #b9d5c3; border-radius: 3px; position: relative; }
.league-mark::after { content: ""; position: absolute; width: 2px; inset: -3px auto -3px 10px; background: var(--orange); }
.masthead-hours { font-size: .87rem; font-weight: 550; color: #e0ede3; }
.masthead-hours span { margin-inline: 6px; color: var(--orange); }

.hero {
  min-height: 198px;
  margin-top: 32px;
  margin-bottom: 28px;
  padding: 34px 42px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  overflow: hidden;
  background: var(--green);
  border-radius: 18px;
  color: var(--white);
}
.hero h1 { font-family: Georgia, serif; font-size: clamp(2.75rem, 6vw, 4.55rem); font-weight: normal; line-height: 1; letter-spacing: -.055em; }
.hero p { margin-top: 14px; color: #e0ede3; font-size: 1.05rem; }
.court { position: relative; width: 242px; height: 112px; flex: 0 0 auto; margin-right: 19px; border: 2px solid #91b19d; border-radius: 8px; transform: rotate(-10deg); }
.court::before, .court::after { content: ""; position: absolute; background: #91b19d; }
.court::before { width: 2px; inset: -10px auto -10px 50%; }
.court::after { height: 2px; inset: calc(50% - 1px) 0 auto; }
.court span { position: absolute; z-index: 1; width: 24px; height: 24px; left: 69%; top: 20%; background: var(--orange); border-radius: 50%; }

.workspace { display: grid; grid-template-columns: minmax(0, 1fr) 286px; gap: 22px; align-items: start; padding-bottom: 38px; }
.schedule, .panel { background: var(--white); border: 1px solid var(--line); border-radius: 15px; }
.schedule { padding: 24px; min-width: 0; }
.schedule-tools { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 12px; margin-bottom: 24px; }
.eyebrow { color: var(--muted); font-size: .72rem; letter-spacing: .11em; font-weight: 750; text-transform: uppercase; }
.schedule h2 { font-size: clamp(1.22rem, 2.1vw, 1.6rem); line-height: 1.25; letter-spacing: -.035em; margin-top: 4px; }
.controls { display: flex; align-items: center; gap: 8px; max-width: 100%; }
.arrow, .controls input {
  min-height: 44px;
  border: 1px solid var(--line);
  background: var(--white);
  border-radius: 8px;
  color: var(--ink);
}
.arrow { min-width: 44px; padding-inline: 8px; font-size: 1.25rem; }
.controls input { width: 143px; min-width: 0; padding: 6px 9px; font-size: .85rem; }
.arrow:hover:enabled, .controls input:hover { background: var(--mint); }
.error { color: var(--warning) !important; font-size: .85rem; margin-bottom: 10px; }

.schedule-matrix { --columns: minmax(90px, .62fr) repeat(2, minmax(0, 1.5fr)); }
.matrix-head, .slot { display: grid; grid-template-columns: var(--columns); gap: 10px; }
.matrix-head { padding: 9px 0; border-radius: 8px; background: var(--mint); color: var(--green-deep); font-size: .73rem; font-weight: 800; text-transform: uppercase; letter-spacing: .09em; }
.matrix-head span { padding-left: 12px; }
.slot { padding: 10px 0; align-items: stretch; border-bottom: 1px solid var(--line); }
.slot:last-child { padding-bottom: 0; border-bottom: 0; }
.slot-time { padding: 9px 0 9px 12px; align-self: center; }
.slot-time strong { display: block; font-size: 1.43rem; line-height: 1.22; font-variant-numeric: tabular-nums; letter-spacing: -.04em; }
.slot-time span { display: block; color: var(--muted); font-size: .75rem; font-weight: 600; }
.table-label { display: none; }
.match { width: 100%; min-height: 78px; padding: 9px 10px; border: 1px solid var(--line); border-radius: 9px; text-align: center; color: var(--ink); transition: background-color .15s, border-color .15s; }
.match:hover { border-color: var(--green); background: var(--mint); }
.open { background: #fafbf6; border-style: dashed; color: var(--muted); font-size: .85rem; font-weight: 650; display: flex; align-items: center; justify-content: center; gap: 8px; }
.add-mark { display: grid; place-items: center; width: 23px; height: 23px; line-height: 1; border-radius: 50%; background: var(--mint); font-size: 1.12rem; color: var(--green); }
.booked { background: #f6f8f1; }
.matchup { display: flex; align-items: center; flex-wrap: wrap; justify-content: center; column-gap: 8px; font-weight: 780; }
.matchup > span { display: inline-flex; align-items: center; gap: 5px; }
.matchup small { color: var(--muted); font-size: .72rem; font-weight: 600; }
.match-action { display: block; margin-top: 3px; color: var(--muted); font-size: .73rem; font-weight: 650; }
.conflict, .conflict:hover { border-color: #b95839; background: var(--warning-bg); }
.conflict .match-action { color: var(--warning); }

.side { display: grid; gap: 14px; }
.panel { padding: 17px 19px; }
.panel-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.panel-heading h2 { font-size: 1rem; letter-spacing: -.015em; }
.panel-heading > span { color: var(--muted); font-size: .75rem; font-weight: 650; white-space: nowrap; }
.meter { background: var(--mint); height: 5px; border-radius: 5px; overflow: hidden; margin: 12px 0; }
.meter span { display: block; height: 100%; background: var(--green); border-radius: 5px; transition: width .15s; }
.check-label { display: flex; align-items: center; gap: 7px; font-size: .84rem; font-weight: 700; }
.check-label span { display: inline-grid; place-items: center; width: 21px; height: 21px; border-radius: 50%; background: var(--mint); }
.check-label.problem { color: var(--warning); }
.check-label.problem span { background: var(--warning-bg); }
.checks ul { color: var(--warning); margin: 5px 0 0; padding-left: 27px; font-size: .82rem; }
.roster { list-style: none; padding: 0; margin: 12px 0 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 7px; }
.roster li { display: flex; align-items: center; gap: 8px; border: 1px solid var(--line); border-radius: 6px; padding: 5px 9px; font-size: .84rem; font-weight: 650; }
.team-dot { width: 9px; height: 9px; flex: 0 0 auto; border-radius: 50%; }
.birch { background: #2d7052; }
.chalk { background: #6b777a; }
.fern { background: #70833e; }
.lark { background: #b47c25; }
.moss { background: #307578; }
.reed { background: #ac5343; }
.primary { min-height: 46px; border: 1px solid var(--green); border-radius: 8px; padding: 8px 15px; background: var(--green); color: var(--white); font-weight: 700; }
.primary:hover { background: var(--green-deep); }
.print-button { display: flex; justify-content: center; align-items: center; gap: 10px; }
.printer { width: 17px; height: 11px; position: relative; border: 1.5px solid currentColor; border-radius: 2px; }
.printer::before, .printer::after { content: ""; position: absolute; left: 3px; right: 3px; height: 6px; border: 1px solid currentColor; background: var(--green); }
.printer::before { top: -6px; }
.printer::after { bottom: -5px; }
.save-status { text-align: center; color: var(--muted); font-size: .76rem; margin-top: -6px; }

dialog { width: min(472px, calc(100% - 28px)); border: 1px solid var(--line); border-radius: 16px; padding: 22px; color: var(--ink); background: var(--white); box-shadow: 0 16px 60px #102e2740; }
dialog::backdrop { background: #0e241cb0; }
.editor-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.editor-heading h2 { margin-top: 2px; font-size: 1.55rem; letter-spacing: -.04em; }
.close { line-height: 1; }
.fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin-top: 18px; }
.fields label { font-size: .85rem; font-weight: 700; }
.fields select { display: block; width: 100%; min-height: 44px; margin-top: 5px; padding-inline: 8px; background: var(--white); color: var(--ink); border: 1px solid var(--line); border-radius: 7px; }
.editor-message { color: var(--warning); background: var(--warning-bg); border-radius: 6px; padding: 8px 10px; margin-top: 12px; font-size: .85rem; }
.editor-actions { display: flex; justify-content: flex-end; flex-wrap: wrap; gap: 8px; margin-top: 20px; }
.clear { min-height: 44px; margin-right: auto; padding: 6px 8px; border: 0; border-radius: 6px; background: transparent; color: var(--warning); font-size: .84rem; font-weight: 700; }
.clear:hover { background: var(--warning-bg); }
.print-sheet { display: none; }

@media (max-width: 900px) {
  .wrap { width: calc(100% - 48px); }
  .workspace { grid-template-columns: 1fr; }
  .side { grid-template-columns: repeat(2, minmax(0, 1fr)); align-items: start; }
  .save-status { margin-top: 0; align-self: center; }
}
@media (max-width: 560px) {
  .wrap { width: calc(100% - 28px); }
  .masthead-inner { min-height: 56px; }
  .masthead-hours { display: none; }
  .hero { margin-top: 18px; margin-bottom: 16px; padding: 23px 17px; min-height: 140px; }
  .hero p { font-size: .92rem; }
  .court { display: none; }
  .workspace { gap: 14px; }
  .schedule { padding: 13px; }
  .schedule-tools { margin-bottom: 15px; }
  .matrix-head { display: none; }
  .slot { grid-template-columns: repeat(2, minmax(0, 1fr)); grid-template-rows: auto auto 1fr; column-gap: 8px; row-gap: 5px; }
  .slot-time { grid-column: 1 / -1; display: flex; align-items: baseline; gap: 5px; padding: 4px 0; }
  .slot-time strong { font-size: 1.24rem; }
  .table-label { display: block; grid-row: 2; font-size: .74rem; font-weight: 750; color: var(--muted); }
  .match { grid-row: 3; }
  .side { grid-template-columns: 1fr; }
  .save-status { margin-top: -4px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

@page { size: portrait; margin: 12mm; }

@media print {
  body { color: #000; background: #fff; font-family: Arial, sans-serif; }
  body > :not(.print-sheet) { display: none !important; }
  .print-sheet { display: block; }
  .print-sheet header { margin-bottom: 8mm; }
  .print-sheet header p { font-size: 19pt; font-weight: bold; }
  .print-sheet h1 { font-size: 38pt; line-height: 1.12; margin: 1mm 0 2mm; }
  .print-sheet table { width: 100%; border-collapse: collapse; table-layout: fixed; text-align: center; }
  .print-sheet th, .print-sheet td { border: 1.5pt solid #000; padding: 2mm; }
  .print-sheet thead th { font-size: 20pt; padding-block: 4mm; }
  .print-sheet thead th:first-child { width: 29%; }
  .print-sheet tbody tr { height: 49mm; break-inside: avoid; }
  .print-sheet tbody th { font-size: 21pt; }
  .print-sheet th span, .print-sheet td span { display: block; font-size: 15pt; }
  .print-sheet td strong { display: block; font-size: 33pt; line-height: 1.06; }
  .print-sheet .print-open { font-size: 21pt; }
  .print-warning { border: 1.5pt solid #000; margin: 0 0 5mm; padding: 2mm 3mm; font-size: 14pt; }
}
